// Headless layer rename across a folder - no document is ever opened
[CommandMethod("RENAMELAYERS", CommandFlags.Session)]
public void RenameLayers()
{
    foreach (string file in System.IO.Directory.GetFiles(@"D:\1042", "*.dwg"))
    {
        using (Database db = new Database(false, true))
        {
            db.ReadDwgFile(file, FileOpenMode.OpenForReadAndAllShare, false, null);
            db.CloseInput(true);

            using (Transaction tr = db.TransactionManager.StartTransaction())
            {
                var lt = (LayerTable)tr.GetObject(db.LayerTableId, OpenMode.ForRead);
                foreach (ObjectId id in lt)
                {
                    var ltr = (LayerTableRecord)tr.GetObject(id, OpenMode.ForRead);
                    if (ltr.Name.StartsWith("OLD-"))
                    {
                        ltr.UpgradeOpen();
                        ltr.Name = "A-" + ltr.Name.Substring(4);
                    }
                }
                tr.Commit();
            }
            db.SaveAs(file, DwgVersion.Current);
        }
    }
}

