// Define a block, then insert it five times
[CommandMethod("MAKETAG")]
public void MakeTag()
{
    Database db = Application.DocumentManager.MdiActiveDocument.Database;
    using (Transaction tr = db.TransactionManager.StartTransaction())
    {
        var bt = (BlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);

        ObjectId defId;
        if (bt.Has("EQUIP_TAG"))
        {
            defId = bt["EQUIP_TAG"];
        }
        else
        {
            var btr = new BlockTableRecord { Name = "EQUIP_TAG", Origin = Point3d.Origin };
            bt.UpgradeOpen();
            defId = bt.Add(btr);
            tr.AddNewlyCreatedDBObject(btr, true);

            var circ = new Circle(Point3d.Origin, Vector3d.ZAxis, 5.0);
            btr.AppendEntity(circ);
            tr.AddNewlyCreatedDBObject(circ, true);
        }

        var ms = (BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace], OpenMode.ForWrite);
        for (int i = 0; i < 5; i++)
        {
            var br = new BlockReference(new Point3d(i * 200.0, 0.0, 0.0), defId) { Layer = "TAGS" };
            ms.AppendEntity(br);
            tr.AddNewlyCreatedDBObject(br, true);
        }
        tr.Commit();
    }
}

