[CommandMethod("COUNTBLOCKS")]
public void CountBlocks()
{
    Document doc = Application.DocumentManager.MdiActiveDocument;
    Editor ed = doc.Editor;

    var filter = new SelectionFilter(new[]
    {
        new TypedValue((int)DxfCode.Start, "INSERT")
    });

    PromptSelectionResult res = ed.SelectAll(filter);
    if (res.Status != PromptStatus.OK) { ed.WriteMessage("\nNo blocks found."); return; }

    var counts = new System.Collections.Generic.Dictionary<string, int>();
    using (Transaction tr = doc.Database.TransactionManager.StartTransaction())
    {
        foreach (SelectedObject so in res.Value)
        {
            var br = (BlockReference)tr.GetObject(so.ObjectId, OpenMode.ForRead);
            string name = br.IsDynamicBlock
                ? ((BlockTableRecord)tr.GetObject(br.DynamicBlockTableRecord, OpenMode.ForRead)).Name
                : br.Name;
            counts[name] = counts.TryGetValue(name, out int c) ? c + 1 : 1;
        }
        tr.Commit();
    }
    foreach (var kv in counts)
        ed.WriteMessage("\n{0,-30} {1,5}", kv.Key, kv.Value);
}

