public ResultBuffer PolyArea(ResultBuffer args)
{
    if (args == null) return null;
    TypedValue[] a = args.AsArray();
    if (a.Length < 1 || a[0].TypeCode != (short)LispDataType.ObjectId) return null;

    Document doc = Application.DocumentManager.MdiActiveDocument;
    double area = 0.0;
    using (Transaction tr = doc.Database.TransactionManager.StartTransaction())
    {
        var ent = tr.GetObject((ObjectId)a[0].Value, OpenMode.ForRead);
        if (ent is Curve c && c.Closed) area = c.Area;
        tr.Commit();
    }
    return new ResultBuffer(new TypedValue((int)LispDataType.Double, area));
}

