// Move every circle smaller than 5 units to a REJECT layer and erase duplicates
[CommandMethod("CLEANHOLES")]
public void CleanHoles()
{
    Document doc = Application.DocumentManager.MdiActiveDocument;
    Database db = doc.Database;
    var seen = new System.Collections.Generic.HashSet<string>();

    using (Transaction tr = db.TransactionManager.StartTransaction())
    {
        var bt = (BlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);
        var ms = (BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace], OpenMode.ForRead);

        foreach (ObjectId id in ms)
        {
            if (id.IsErased) continue;
            var ent = tr.GetObject(id, OpenMode.ForRead);
            if (!(ent is Circle c)) continue;

            string key = $"{c.Center.X:F4},{c.Center.Y:F4},{c.Radius:F4}";
            if (!seen.Add(key))
            {
                c.UpgradeOpen();
                c.Erase();
                continue;
            }
            if (c.Radius < 5.0)
            {
                c.UpgradeOpen();
                c.Layer = "REJECT";
            }
        }
        tr.Commit();
    }
    doc.Editor.Regen();
}

