void myCmdFunc()
{
    ads_point centre;
    acedInitGet(RSG_NONULL, NULL);
    if (acedGetPoint(NULL, _T("\nCentre of bolt circle: "), centre) != RTNORM)
        return;

    double pcd;
    acedInitGet(RSG_NONULL | RSG_NOZERO | RSG_NONEG, NULL);
    if (acedGetReal(_T("\nPitch circle diameter: "), &pcd) != RTNORM)
        return;

    int n = 8;
    acedInitGet(RSG_NONULL | RSG_NOZERO | RSG_NONEG, NULL);
    if (acedGetInt(_T("\nNumber of holes <8>: "), &n) == RTCAN)
        return;

    for (int i = 0; i < n; ++i)
    {
        double a = 2.0 * 3.14159265358979 * i / n;
        ads_point p;
        p[X] = centre[X] + (pcd / 2.0) * cos(a);
        p[Y] = centre[Y] + (pcd / 2.0) * sin(a);
        p[Z] = 0.0;
        acedCommandS(RTSTR, _T("_.CIRCLE"), RTPOINT, p, RTREAL, 5.0, RTNONE);
    }
    acutPrintf(_T("\n%d holes placed."), n);
}

