void drawPlate()
{
    AcGePoint3d p1(0.0, 0.0, 0.0), p2(200.0, 0.0, 0.0);

    AcDbBlockTable* pTable = NULL;
    if (acdbHostApplicationServices()->workingDatabase()
            ->getBlockTable(pTable, AcDb::kForRead) != Acad::eOk) return;

    AcDbBlockTableRecord* pRec = NULL;
    if (pTable->getAt(ACDB_MODEL_SPACE, pRec, AcDb::kForWrite) != Acad::eOk)
    {
        pTable->close();
        return;
    }
    pTable->close();

    AcDbLine* pLine = new AcDbLine(p1, p2);
    pLine->setLayer(_T("OUTLINE"));

    AcDbObjectId lineId;
    if (pRec->appendAcDbEntity(lineId, pLine) != Acad::eOk)
        delete pLine;                 // never appended: we still own it
    else
        pLine->close();

    AcDbCircle* pCirc = new AcDbCircle(AcGePoint3d(100.0, 60.0, 0.0),
                                       AcGeVector3d::kZAxis, 8.0);
    AcDbObjectId circId;
    if (pRec->appendAcDbEntity(circId, pCirc) != Acad::eOk)
        delete pCirc;
    else
        pCirc->close();

    pRec->close();
}

